mapper.select:
( SELECT * FROM promotion
in_page = 0 AND start_date <= CONVERT_TZ(CURRENT_DATE, '+00:00', '-06:00') AND ( end_date IS NULL OR end_date >= CONVERT_TZ(CURRENT_DATE, '+00:00', '-06:00') )
AND type = #{type}
) ORDER BY promotion_id DESC

( SELECT * FROM promotion
in_page = 1 AND start_date <= CONVERT_TZ(CURRENT_DATE, '+00:00', '-06:00') AND ( end_date IS NULL OR end_date >= CONVERT_TZ(CURRENT_DATE, '+00:00', '-06:00') )
AND type = #{type}
) ORDER BY promotion_id DESC
